// Normalise one sheet row into a Facebook job.
// Column headers are matched case-insensitively, so renaming one in the sheet
// doesn't break this.

// Canonical platform ids. Used for BOTH layouts: a TRUE/FALSE column per
// platform (what this sheet uses) and a single comma-separated column.
const PLATFORM_ALIASES = {
  facebook: 'facebook', fb: 'facebook', 'facebook page': 'facebook',
  instagram: 'instagram', ig: 'instagram', insta: 'instagram',
  twitter: 'twitter', x: 'twitter', 'x / twitter': 'twitter', 'twitter / x': 'twitter',
  linkedin: 'linkedin', li: 'linkedin',
  youtube: 'youtube', yt: 'youtube', shorts: 'youtube',
};

function pick(row, names) {
  for (const name of names) {
    const key = Object.keys(row).find((k) => k.trim().toLowerCase() === name);
    if (key && row[key] !== '' && row[key] !== null && row[key] !== undefined) return row[key];
  }
  return '';
}

// A ticked checkbox arrives as a real boolean; a typed one as text.
function truthy(v) {
  if (v === true) return true;
  const s = String(v).trim().toLowerCase();
  return s === 'true' || s === 'yes' || s === 'y' || s === '1' || s === 'x';
}

function platformsFrom(row) {
  const found = new Set();
  // (a) one TRUE column per platform
  for (const key of Object.keys(row)) {
    const canon = PLATFORM_ALIASES[key.trim().toLowerCase()];
    if (canon && truthy(row[key])) found.add(canon);
  }
  // (b) or a single comma-separated column, if the sheet ever grows one
  String(pick(row, ['platforms', 'channels', 'accounts', 'social']))
    .split(/[,;|]/)
    .map((s) => s.trim().toLowerCase())
    .filter(Boolean)
    .forEach((s) => { const c = PLATFORM_ALIASES[s]; if (c) found.add(c); });
  return [...found];
}

// Google Sheets can hand back a schedule three different ways depending on how
// the cell was formatted, so accept all of them rather than trust one.
function parseWhen(v) {
  if (v === '' || v === null || v === undefined) return null;
  if (v instanceof Date) return v;
  if (typeof v === 'number') {
    // Sheets serial date: days since 1899-12-30, in the spreadsheet's timezone
    return new Date(Math.round((v - 25569) * 86400000));
  }
  const d = new Date(String(v).trim());
  return isNaN(d.getTime()) ? null : d;
}

function readCommon(row) {
  const driveUrl = String(pick(row, ['gdrive url', 'drive url', 'google drive url', 'gdrive', 'url', 'link', 'media']));
  let fileId = String(pick(row, ['file id', 'fileid', 'drive file id', 'gdrive id']));
  if (!fileId) {
    const m = driveUrl.match(/\/d\/([a-zA-Z0-9_-]{10,})/) || driveUrl.match(/[?&]id=([a-zA-Z0-9_-]{10,})/);
    fileId = m ? m[1] : '';
  }

  // The cell holds one URL, or several comma-separated for a carousel. Blotato
  // fetches each itself, so they have to be public — the form already requires
  // "anyone with the link". If an image ever fails, try
  // https://lh3.googleusercontent.com/d/<fileId> instead.
  const fileIds = driveUrl
    .split(',')
    .map((s) => s.trim())
    .filter(Boolean)
    .map((u) => {
      const m = u.match(/\/d\/([a-zA-Z0-9_-]{10,})/) || u.match(/[?&]id=([a-zA-Z0-9_-]{10,})/);
      return m ? m[1] : (/^[a-zA-Z0-9_-]{10,}$/.test(u) ? u : '');
    })
    .filter(Boolean);
  const mediaUrls = fileIds.map((id) => `https://drive.google.com/uc?export=download&id=${id}`);
  // Same files, other host. Drive serves media from two and either can
  // refuse depending on the file, so a failure below names the one to try.
  const altUrls = fileIds.map((id) => `https://lh3.googleusercontent.com/d/${id}`);

  // n8n owns `post status`. 'queued' means untouched; anything else means a
  // previous run already claimed or finished the row, so hands off — otherwise
  // an approved row would be re-published on every single sweep.
  const postStatus = String(pick(row, ['post status', 'automation status', 'publish status'])).trim().toLowerCase();
  const unclaimed = postStatus === '' || postStatus === 'queued';

  // The human gate. n8n reads this column but never writes it, so it stays on
  // 'Publish' after a post goes out — which is exactly why `unclaimed` above is
  // what actually stops a repeat, not this.
  const approved = String(pick(row, ['status', 'state'])).trim().toLowerCase() === 'publish';

  // Blank publish time means "go on the next sweep"; unreadable is an error,
  // not a licence to publish immediately.
  const scheduledRaw = pick(row, ['post at', 'publish at', 'schedule', 'scheduled', 'scheduled at', 'post date', 'publish date']);
  const hasSchedule = scheduledRaw !== '' && scheduledRaw !== null && scheduledRaw !== undefined;
  const dueAt = hasSchedule ? parseWhen(scheduledRaw) : null;
  const badSchedule = hasSchedule && !dueAt;
  const isDue = !hasSchedule || (!!dueAt && dueAt.getTime() <= Date.now());

  return {
    driveUrl,
    fileId,
    fileIds,
    mediaUrls,
    altUrls,
    caption: String(pick(row, ['caption', 'text', 'post caption', 'message', 'content'])),
    platforms: platformsFrom(row),
    approved,
    unclaimed,
    dueAt,
    badSchedule,
    isDue,
  };
}

return $input.all().map((item, i) => {
  const row = item.json;
  const c = readCommon(row);

  const targetsFacebook = c.platforms.includes('facebook');
  const ignored = c.platforms.filter((p) => p !== 'facebook');

  const problems = [];
  if (!c.mediaUrls.length) problems.push('no usable media link');
  if (!c.caption) problems.push('empty caption');
  if (c.badSchedule) problems.push('unreadable publish time');

  let valid = true;
  let skipStatus = '';
  let skipReason = '';

  if (!targetsFacebook) {
    valid = false;
    skipStatus = 'skipped';
    skipReason = c.platforms.length
      ? `row targets ${c.platforms.join(', ')} — this backend only publishes to Facebook`
      : 'no platforms ticked';
  } else if (problems.length) {
    valid = false;
    skipStatus = 'failed';
    skipReason = problems.join('; ');
  }

  return {
    json: {
      row_number: row.row_number,
      driveUrl: c.driveUrl,
      fileId: c.fileIds[0] || '',
      caption: c.caption,
      platforms: c.platforms,
      ignored,
      mediaUrls: c.mediaUrls,
      scheduledAt: c.dueAt ? c.dueAt.toISOString() : '',
      approved: c.approved && c.unclaimed,
      isDue: c.isDue,
      valid,
      skipStatus,
      skipReason,
    },
    pairedItem: { item: i },
  };
});

// Blotato re-hosts each file keeping its real extension, so the URLs it
// returns tell us whether this is a video post — which decides target.mediaType.
const VIDEO_EXT = /\.(mp4|mov|m4v|webm|mkv|avi)(\?|$)/i;
const MEDIA_LIMIT = 30;   // Facebook album ceiling

return $input.all().map((item, i) => {
  const job = item.json;
  const urls = job.mediaUrls || [];
  const isVideo = urls.length === 1 && VIDEO_EXT.test(urls[0]);
  const anyVideo = urls.some((u) => VIDEO_EXT.test(u));

  let uploadError = '';
  if (!urls.length) uploadError = job.uploadErrors || 'Blotato returned no media URL — check the Drive files are shared "anyone with the link"';
  else if (anyVideo && urls.length > 1) uploadError = 'video cannot be mixed into a carousel';
  else if (urls.length > MEDIA_LIMIT) uploadError = `${urls.length} media items, Facebook allows ${MEDIA_LIMIT}`;

  return {
    json: {
      ...job,
      mediaUrl: urls.join(','),   // the Blotato node splits this back into an array
      mediaCount: urls.length,
      isVideo,
      uploadOk: !uploadError,
      uploadError,
    },
    pairedItem: { item: i },
  };
});

// Rows this backend can never publish — write the reason back so they stop
// being picked up on every sweep.
return $input.all().map((item) => ({
  json: {
    row_number: item.json.row_number,
    status: item.json.skipStatus || 'failed',
    result: (item.json.skipStatus === 'skipped' ? 'Skipped — ' : 'Failed — ') + item.json.skipReason,
    processedAt: new Date().toISOString(),
  },
}));

// One item per media URL, so the Blotato upload node can run over them.
// Carousel order is the sheet's order, so the index rides along and is used to
// rebuild the list after the uploads finish out of order.
const jobs = new Map($('Prepare jobs').all().map((i) => [String(i.json.row_number), i.json]));
const out = [];

$input.all().forEach((item, i) => {
  const job = jobs.get(String(item.json.row_number));
  if (!job) return;
  (job.mediaUrls || []).forEach((url, idx) => {
    out.push({
      json: { row_number: job.row_number, idx, sourceUrl: url, altUrl: (job.altUrls || [])[idx] || '' },
      pairedItem: { item: i },
    });
  });
});

return out;

// Rebuild one item per row, with its media back in the original order.
// Uploads finish whenever they finish, so position comes from the index we
// carried through rather than from arrival order.
const sent = $('Split media').all();
const jobs = new Map($('Prepare jobs').all().map((i) => [String(i.json.row_number), i.json]));
const byRow = new Map();

$input.all().forEach((item, i) => {
  const s = (sent[i] && sent[i].json) || {};
  const key = String(s.row_number);
  if (!byRow.has(key)) byRow.set(key, { row_number: s.row_number, slots: [], errors: [] });
  const g = byRow.get(key);

  const res = item.json || {};
  if (res.url) {
    g.slots[s.idx] = String(res.url);
  } else {
    // The Blotato node reports failures as a plain string on `error`.
    g.errors.push('item ' + (s.idx + 1) + ': ' +
      (res.error ? String(res.error.message || res.error) : 'no URL returned') +
      // Name the other host explicitly — it is the fix in most cases, and
      // nobody reading the sheet would otherwise know to try it.
      (s.altUrl ? ' (retry with ' + s.altUrl + ')' : ''));
  }
});

return [...byRow.values()].map((g) => {
  const job = jobs.get(String(g.row_number)) || {};
  return {
    json: {
      ...job,
      mediaUrls: g.slots.filter(Boolean),   // holes from failed uploads collapse
      uploadErrors: g.errors.join('; '),
    },
  };
});
